package palindrome

import (
	"fmt"
	"strconv"
)

// Product holds a palindromic product value and all of its factor pairs
// within the given range.
type Product struct {
	Product        int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products of two
// numbers in the range [fmin, fmax], along with all factor pairs for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, fmt.Errorf("fmin > fmax")
	}

	var min, max Product
	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			p := i * j
			if !isPalindrome(p) {
				continue
			}
			if len(min.Factorizations) == 0 || p < min.Product {
				min = Product{p, [][2]int{{i, j}}}
			} else if p == min.Product {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			if len(max.Factorizations) == 0 || p > max.Product {
				max = Product{p, [][2]int{{i, j}}}
			} else if p == max.Product {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if len(min.Factorizations) == 0 {
		return Product{}, Product{}, fmt.Errorf("no palindromes")
	}
	return min, max, nil
}

func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

